export type AudienceLocale = 'en' | 'fr';

export const defaultAudienceLabels = {
  title: 'Audience', visitsTitle: 'Landing page visits', visitsLast: (days: number) => `Last ${days} days`, total: 'Visits', day: 'Day', visits: 'Visits',
  outreachTitle: 'Outreach links', outreachHint: 'Visits through a link ending in ?ref=<id>', ref: 'Link', outreachShare: (percent: number) => `${percent}% of visits came through an outreach link`,
  noVisits: 'No visit yet', noVisitsDescription: 'Visits appear here once the landing page is shared.', noRefs: 'No outreach link visited yet',
  unavailable: 'Visit totals are not available on this host yet.', totalsOnly: 'Totals only: no address and no browser are kept.',
  requestsTitle: 'Access requests', requestsEmpty: 'No pending request', requestsInHub: 'Access requests are handled in the hub, on the app card.',
  email: 'Address', note: 'Note', since: 'Since', grant: 'Grant access', dismiss: 'Dismiss', revokedBefore: 'Had access before',
  usageTitle: 'Usage', usageHint: 'Counts only, never the data', sample: 'Tried the sample', ownFile: 'Used their own file', noUsage: 'This app does not count its usage yet.',
  formatDay: (day: string) => day,
  loading: 'Loading', failed: 'The audience could not be loaded.', retry: 'Try again',
};
export type AudienceLabels = typeof defaultAudienceLabels;

const dayFormat = (locale: string) => {
  const formatter = new Intl.DateTimeFormat(locale, { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'UTC' });
  return (day: string) => { const date = new Date(`${day}T00:00:00Z`); return Number.isNaN(date.getTime()) ? day : formatter.format(date); };
};

export const frenchAudienceLabels: AudienceLabels = {
  title: 'Audience', visitsTitle: 'Visites de la page d’accueil', visitsLast: (days) => `${days} derniers jours`, total: 'Visites', day: 'Jour', visits: 'Visites',
  outreachTitle: 'Liens de prospection', outreachHint: 'Visites par un lien terminé par ?ref=<id>', ref: 'Lien', outreachShare: (percent) => `${percent} % des visites viennent d’un lien de prospection`,
  noVisits: 'Aucune visite pour l’instant', noVisitsDescription: 'Les visites apparaissent ici dès que la page d’accueil est partagée.', noRefs: 'Aucun lien de prospection visité',
  unavailable: 'Les totaux de visites ne sont pas encore disponibles sur cet hébergeur.', totalsOnly: 'Des totaux uniquement : ni adresse ni navigateur ne sont conservés.',
  requestsTitle: 'Demandes d’accès', requestsEmpty: 'Aucune demande en attente', requestsInHub: 'Les demandes d’accès se traitent dans le hub, sur la carte de l’app.',
  email: 'Adresse', note: 'Note', since: 'Depuis', grant: 'Donner l’accès', dismiss: 'Écarter', revokedBefore: 'Avait déjà eu accès',
  usageTitle: 'Usage', usageHint: 'Des comptes uniquement, jamais les données', sample: 'Ont essayé l’exemple', ownFile: 'Ont utilisé leur propre fichier', noUsage: 'Cette app ne compte pas encore son usage.',
  formatDay: dayFormat('fr'),
  loading: 'Chargement', failed: 'L’audience n’a pas pu être chargée.', retry: 'Réessayer',
};

export function audienceLabelsFor(locale: AudienceLocale | undefined, overrides: Partial<AudienceLabels> = {}): AudienceLabels {
  const base = locale === 'fr' ? frenchAudienceLabels : { ...defaultAudienceLabels, formatDay: dayFormat('en') };
  return { ...base, ...overrides };
}

// The Audience screen's data and what it derives from it. Totals only: a visit is a count, a usage is a count; no person, address or file is here.

export interface LandingDay { readonly day: string; readonly visits: number; readonly refs: Readonly<Record<string, number>> }
export interface LandingTotals { readonly days: readonly LandingDay[]; readonly total: number; readonly refs: Readonly<Record<string, number>> }
/** One counter the app keeps itself (see README.md "Usage counts"): `kind` is `sample` (the sample file) or `own_file` (the person's own), or any other word the app counts. */
export interface UsageCount { readonly kind: string; readonly n: number }
/** A stranger's request for access, as the owner sees it. */
export interface AccessRequestRow { readonly email: string; readonly note: string; readonly createdAt: string; readonly revokedBefore: boolean }
/** What the app's `/api/audience` route answers (server/src/audience.ts): `landing` is null on a host without env.landing, `usage` null when the app keeps no counter. */
export interface AudienceData { readonly landing: LandingTotals | null; readonly usage: readonly UsageCount[] | null }

export interface RefRow { readonly ref: string; readonly visits: number; readonly share: number }
export interface DayRow { readonly day: string; readonly visits: number; readonly share: number }

/** The outreach links, most visited first (ties by name); `share` is the part of the busiest one, 0 to 100, for a bar. */
export function refRows(landing: LandingTotals | null): readonly RefRow[] {
  const entries = Object.entries(landing?.refs ?? {}).filter(([, n]) => n > 0).sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1));
  const top = entries[0]?.[1] ?? 0;
  return entries.map(([ref, visits]) => ({ ref, visits, share: top ? Math.round((visits / top) * 100) : 0 }));
}

/** The last `count` days, newest first, with a bar share against the busiest of them. A quiet stretch still shows its days. */
export function dayRows(landing: LandingTotals | null, count = 14): readonly DayRow[] {
  const last = (landing?.days ?? []).slice(-Math.max(1, count));
  const top = Math.max(0, ...last.map((d) => d.visits));
  return last.map((d) => ({ day: d.day, visits: d.visits, share: top ? Math.round((d.visits / top) * 100) : 0 })).reverse();
}

/** The visits through outreach links as a part of all visits, 0 to 100 (0 when there is none). */
export function outreachShare(landing: LandingTotals | null): number {
  if (!landing?.total) return 0;
  return Math.round((Object.values(landing.refs).reduce((a, b) => a + b, 0) / landing.total) * 100);
}

/** The count of one usage kind (0 when the app never counted it). */
export const usageOf = (usage: readonly UsageCount[] | null, kind: string): number => usage?.find((u) => u.kind === kind)?.n ?? 0;

/** `/api/audience` answer, checked: anything that is not the shape is dropped to null, never thrown into the page. */
export function readAudience(value: unknown): AudienceData {
  const v = (value ?? {}) as { landing?: unknown; usage?: unknown };
  const landing = v.landing as Partial<LandingTotals> | null | undefined;
  const okLanding = landing && Array.isArray(landing.days) && typeof landing.total === 'number' && landing.refs && typeof landing.refs === 'object';
  const usage = Array.isArray(v.usage) ? v.usage.filter((u): u is UsageCount => typeof u?.kind === 'string' && Number.isFinite(u?.n)) : null;
  return { landing: okLanding ? (landing as LandingTotals) : null, usage };
}

'use client';

import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from '@/components/ui/empty';
import { Progress } from '@/components/ui/progress';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { audienceLabelsFor } from './audience-labels';
import type { AudienceLabels, AudienceLocale } from './audience-labels';
import { dayRows, outreachShare, refRows, usageOf } from './audience-model';
import type { AccessRequestRow, AudienceData } from './audience-model';

export interface AudienceRequests {
  readonly items: readonly AccessRequestRow[];
  readonly onGrant: (email: string) => void;
  readonly onDismiss: (email: string) => void;
}

export interface AudienceProps {
  /** Null while loading. */
  readonly data: AudienceData | null;
  readonly error?: boolean;
  /** Access requests with their actions; absent: the screen says they are handled in the hub. */
  readonly requests?: AudienceRequests;
  readonly labels?: Partial<AudienceLabels>;
  readonly locale?: AudienceLocale;
  readonly onRetry?: () => void;
}

interface BarRow { readonly key: string; readonly name: string; readonly visits: number; readonly share: number }

/** A name, a bar against the busiest row, and the count. */
function BarTable({ head, rows, labels }: { head: string; rows: readonly BarRow[]; labels: AudienceLabels }) {
  return <Table>
    <TableHeader>
      <TableRow>
        <TableHead>{head}</TableHead>
        <TableHead className="w-1/2"><span className="sr-only">{labels.visits}</span></TableHead>
        <TableHead className="text-end">{labels.visits}</TableHead>
      </TableRow>
    </TableHeader>
    <TableBody>
      {rows.map((row) => <TableRow key={row.key}>
        <TableCell>{row.name}</TableCell>
        <TableCell><Progress value={row.share} aria-label={`${row.name}: ${row.visits}`} /></TableCell>
        <TableCell className="text-end tabular-nums">{row.visits}</TableCell>
      </TableRow>)}
    </TableBody>
  </Table>;
}

function Placeholder({ title, description }: { title: string; description: string }) {
  return <Empty><EmptyHeader><EmptyTitle>{title}</EmptyTitle><EmptyDescription>{description}</EmptyDescription></EmptyHeader></Empty>;
}

function Visits({ data, labels }: { data: AudienceData; labels: AudienceLabels }) {
  if (!data.landing) return <Placeholder title={labels.visitsTitle} description={labels.unavailable} />;
  if (!data.landing.total) return <Placeholder title={labels.noVisits} description={labels.noVisitsDescription} />;
  const rows = dayRows(data.landing, 14).map((d) => ({ key: d.day, name: labels.formatDay(d.day), visits: d.visits, share: d.share }));
  return <Card>
    <CardHeader>
      <CardTitle>{labels.visitsTitle} <Badge variant="secondary">{data.landing.total}</Badge></CardTitle>
      <CardDescription>{labels.visitsLast(rows.length)} · {labels.totalsOnly}</CardDescription>
    </CardHeader>
    <CardContent><BarTable head={labels.day} rows={rows} labels={labels} /></CardContent>
  </Card>;
}

function Outreach({ data, labels }: { data: AudienceData; labels: AudienceLabels }) {
  const rows = refRows(data.landing).map((r) => ({ key: r.ref, name: r.ref, visits: r.visits, share: r.share }));
  const hint = rows.length ? labels.outreachShare(outreachShare(data.landing)) : labels.outreachHint;
  return <Card>
    <CardHeader><CardTitle>{labels.outreachTitle}</CardTitle><CardDescription>{hint}</CardDescription></CardHeader>
    <CardContent>
      {rows.length ? <BarTable head={labels.ref} rows={rows} labels={labels} /> : <p className="text-sm text-muted-foreground">{labels.noRefs}</p>}
    </CardContent>
  </Card>;
}

function RequestRow({ item, requests, labels }: { item: AccessRequestRow; requests: AudienceRequests; labels: AudienceLabels }) {
  return <TableRow>
    <TableCell>{item.email}{item.revokedBefore && <> <Badge variant="outline">{labels.revokedBefore}</Badge></>}</TableCell>
    <TableCell className="whitespace-normal">{item.note}</TableCell>
    <TableCell className="text-end">
      <Button size="sm" onClick={() => requests.onGrant(item.email)}>{labels.grant}</Button>{' '}
      <Button size="sm" variant="ghost" onClick={() => requests.onDismiss(item.email)}>{labels.dismiss}</Button>
    </TableCell>
  </TableRow>;
}

function Requests({ requests, labels }: { requests?: AudienceRequests; labels: AudienceLabels }) {
  const count = requests?.items.length ?? 0;
  return <Card>
    <CardHeader>
      <CardTitle>{labels.requestsTitle}{count > 0 && <> <Badge>{count}</Badge></>}</CardTitle>
      {!requests && <CardDescription>{labels.requestsInHub}</CardDescription>}
    </CardHeader>
    {requests && <CardContent>
      {count ? <Table>
        <TableHeader>
          <TableRow>
            <TableHead>{labels.email}</TableHead>
            <TableHead>{labels.note}</TableHead>
            <TableHead><span className="sr-only">{labels.grant}</span></TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>{requests.items.map((item) => <RequestRow key={item.email} item={item} requests={requests} labels={labels} />)}</TableBody>
      </Table> : <p className="text-sm text-muted-foreground">{labels.requestsEmpty}</p>}
    </CardContent>}
  </Card>;
}

function Usage({ data, labels }: { data: AudienceData; labels: AudienceLabels }) {
  const count = (kind: string, name: string) => <TableRow>
    <TableCell>{name}</TableCell>
    <TableCell className="text-end tabular-nums">{usageOf(data.usage, kind)}</TableCell>
  </TableRow>;
  return <Card>
    <CardHeader><CardTitle>{labels.usageTitle}</CardTitle><CardDescription>{data.usage ? labels.usageHint : labels.noUsage}</CardDescription></CardHeader>
    {data.usage && <CardContent><Table><TableBody>{count('sample', labels.sample)}{count('own_file', labels.ownFile)}</TableBody></Table></CardContent>}
  </Card>;
}

/** The Audience screen: presentation only. The app loads `/api/audience` (server/src/audience.ts) and hands the answer in; the host decides who may read it. */
export function Audience(props: AudienceProps) {
  const labels = audienceLabelsFor(props.locale, props.labels);
  const { data, error } = props;
  if (error) {
    return <Empty>
      <EmptyHeader><EmptyTitle>{labels.failed}</EmptyTitle></EmptyHeader>
      {props.onRetry && <Button variant="outline" onClick={props.onRetry}>{labels.retry}</Button>}
    </Empty>;
  }
  if (!data) return <p className="text-sm text-muted-foreground" role="status">{labels.loading}</p>;
  return <section aria-label={labels.title} className="flex flex-col gap-4" data-testid="audience">
    <Visits data={data} labels={labels} />
    <Outreach data={data} labels={labels} />
    <Requests requests={props.requests} labels={labels} />
    <Usage data={data} labels={labels} />
  </section>;
}

'use client';

import { useEffect, useState } from 'react';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Spinner } from '@/components/ui/spinner';
import type { OutreachLabels } from './outreach-labels';
import type { OutgoingMessage, Prepared } from './outreach-model';

export interface SendActions {
  /** The owner's click: the host checks everything and answers what would go out, with the single-use confirm token. Rejects with an error whose `code` is the host's (`footer_missing`, `suppressed`...). */
  readonly onPrepare: (message: OutgoingMessage) => Promise<Prepared>;
  /** The owner's confirm: one send with that token. */
  readonly onSend: (message: OutgoingMessage, confirm: string) => Promise<void>;
}

interface Props extends SendActions {
  /** The message to confirm; null: closed. */
  readonly message: OutgoingMessage | null;
  readonly labels: OutreachLabels;
  readonly onClose: (sent: boolean) => void;
}

const codeOf = (error: unknown): string => (error && typeof error === 'object' && 'code' in error ? String((error as { code: unknown }).code) : '');

/** The confirm-to-send dialog: shows exactly what the host would send (footer included) and sends only on the click. Used for first sends and replies alike. */
export function ConfirmSend({ message, labels, onClose, onPrepare, onSend }: Props) {
  const [prepared, setPrepared] = useState<Prepared | null>(null);
  const [failure, setFailure] = useState('');
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    setPrepared(null); setFailure(''); setBusy(false);
    if (!message) return;
    let live = true;
    onPrepare(message).then((p) => { if (live) setPrepared(p); }).catch((e: unknown) => { if (live) setFailure(labels.errors[codeOf(e)] ?? labels.failed); });
    return () => { live = false; };
  }, [message]); // eslint-disable-line react-hooks/exhaustive-deps
  const confirm = async () => {
    if (!message || !prepared) return;
    setBusy(true);
    try { await onSend(message, prepared.confirm); onClose(true); } catch (e) { setFailure(labels.errors[codeOf(e)] ?? labels.failed); setPrepared(null); setBusy(false); }
  };
  return <Dialog open={message !== null} onOpenChange={(open) => { if (!open && !busy) onClose(false); }}>
    <DialogContent>
      <DialogHeader>
        <DialogTitle>{labels.confirmTitle}</DialogTitle>
        <DialogDescription>{labels.confirmDescription}</DialogDescription>
      </DialogHeader>
      {failure && <Alert variant="destructive"><AlertDescription>{failure}</AlertDescription></Alert>}
      {!prepared && !failure && <p className="flex items-center gap-2 text-sm text-muted-foreground" role="status"><Spinner />{labels.preparing}</p>}
      {prepared && <div className="flex flex-col gap-2 text-sm" data-testid="confirm-preview">
        <p><span className="text-muted-foreground">{labels.from}</span> {prepared.from}</p>
        <p><span className="text-muted-foreground">{labels.to}</span> {prepared.to}</p>
        <p><span className="text-muted-foreground">{labels.subject}</span> {prepared.subject}</p>
        <pre className="max-h-64 overflow-auto rounded-md bg-muted p-3 text-xs whitespace-pre-wrap">{prepared.text}</pre>
        <p className="text-muted-foreground">{labels.quota(prepared.remaining, 20)}</p>
      </div>}
      <DialogFooter>
        <Button variant="outline" disabled={busy} onClick={() => onClose(false)}>{labels.cancel}</Button>
        <Button disabled={!prepared || busy} onClick={confirm}>{busy ? labels.sending : labels.confirm}</Button>
      </DialogFooter>
    </DialogContent>
  </Dialog>;
}

'use client';

import { useState } from 'react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from '@/components/ui/empty';
import { Textarea } from '@/components/ui/textarea';
import { ConfirmSend } from './confirm-send';
import type { SendActions } from './confirm-send';
import type { OutreachLabels } from './outreach-labels';
import { replySubject } from './outreach-model';
import type { InboxThreadRow, OutgoingMessage, ThreadMessage, ThreadView } from './outreach-model';

export interface InboxPanelProps extends SendActions {
  readonly threads: readonly InboxThreadRow[];
  readonly unread: number;
  /** Opens a thread (the host marks it read); the app refreshes the list after. */
  readonly onOpen: (thread: string) => Promise<ThreadView>;
  /** Called after a reply went out or a thread was read, so the app reloads `/api/outreach`. */
  readonly onChanged: () => void;
  readonly labels: OutreachLabels;
}

function Bubble({ message, labels }: { message: ThreadMessage; labels: OutreachLabels }) {
  const incoming = message.direction === 'in';
  return <div className="flex flex-col gap-1 rounded-md border p-3 text-sm">
    <p className="text-xs text-muted-foreground">{incoming ? `${labels.incoming} · ${message.from}` : `${labels.outgoing} · ${message.to}`} · {labels.formatTime(message.at)}</p>
    {incoming ? <p className="whitespace-pre-wrap" data-testid="inbound-text">{message.text}</p> : <p>{message.subject}</p>}
  </div>;
}

/** The last message of the other side: what a reply answers. */
const lastIncoming = (view: ThreadView): Extract<ThreadMessage, { direction: 'in' }> | undefined =>
  [...view.messages].reverse().find((m): m is Extract<ThreadMessage, { direction: 'in' }> => m.direction === 'in');

function ThreadDialog({ view, onClose, onReply, labels }: { view: ThreadView | null; onClose: () => void; onReply: (m: OutgoingMessage) => void; labels: OutreachLabels }) {
  const [text, setText] = useState('');
  const last = view ? lastIncoming(view) : undefined;
  const review = () => {
    if (!view || !last || !text.trim()) return;
    onReply({ to: last.from, draft: view.draft || 'reply', subject: replySubject(last.subject), text: text.trim(), ref: view.ref || 'reply', inReplyTo: last.messageId });
    setText('');
  };
  return <Dialog open={view !== null} onOpenChange={(open) => { if (!open) onClose(); }}>
    <DialogContent>
      <DialogHeader>
        <DialogTitle>{last?.subject ?? labels.inboxTitle}</DialogTitle>
        <DialogDescription>{labels.notAVerifiedSender}</DialogDescription>
      </DialogHeader>
      <div className="flex max-h-80 flex-col gap-2 overflow-auto">{view?.messages.map((m) => <Bubble key={m.id} message={m} labels={labels} />)}</div>
      <Textarea aria-label={labels.reply} placeholder={labels.replyPlaceholder} value={text} maxLength={20000} onChange={(e) => setText(e.target.value)} />
      <DialogFooter>
        <Button variant="outline" onClick={onClose}>{labels.close}</Button>
        <Button disabled={!text.trim() || !last} onClick={review}>{labels.review}</Button>
      </DialogFooter>
    </DialogContent>
  </Dialog>;
}

function ThreadRow({ thread, onOpen, labels }: { thread: InboxThreadRow; onOpen: (t: InboxThreadRow) => void; labels: OutreachLabels }) {
  return <li className="flex items-center justify-between gap-3 rounded-md border p-3 text-sm">
    <div className="min-w-0">
      <p className="truncate font-medium">{thread.subject}{thread.unread > 0 && <> <Badge>{labels.unread(thread.unread)}</Badge></>}</p>
      <p className="truncate text-muted-foreground">{thread.from} · {labels.formatTime(thread.lastAt)}{thread.ref && <> · {thread.ref}</>}</p>
    </div>
    <Button size="sm" variant="outline" aria-label={`${labels.open} ${thread.subject}`} onClick={() => onOpen(thread)}>{labels.open}</Button>
  </li>;
}

/** The Inbox: replies that came back to the app's address, by thread, linked to the draft and the recipient. A reply goes out through the same confirm dialog. */
export function InboxPanel({ threads, unread, onOpen, onChanged, onPrepare, onSend, labels }: InboxPanelProps) {
  const [view, setView] = useState<ThreadView | null>(null);
  const [reply, setReply] = useState<OutgoingMessage | null>(null);
  const open = async (t: InboxThreadRow) => { setView(await onOpen(t.thread)); onChanged(); };
  return <Card data-testid="inbox">
    <CardHeader>
      <CardTitle>{labels.inboxTitle}{unread > 0 && <> <Badge>{labels.unread(unread)}</Badge></>}</CardTitle>
      <CardDescription>{labels.inboxEmptyDescription}</CardDescription>
    </CardHeader>
    <CardContent>
      {threads.length
        ? <ul className="flex flex-col gap-2">{threads.map((t) => <ThreadRow key={t.thread} thread={t} onOpen={open} labels={labels} />)}</ul>
        : <Empty><EmptyHeader><EmptyTitle>{labels.inboxEmpty}</EmptyTitle><EmptyDescription>{labels.inboxEmptyDescription}</EmptyDescription></EmptyHeader></Empty>}
    </CardContent>
    <ThreadDialog view={reply ? null : view} onClose={() => setView(null)} onReply={setReply} labels={labels} />
    <ConfirmSend message={reply} labels={labels} onPrepare={onPrepare} onSend={onSend}
      onClose={(sent) => { setReply(null); if (sent) { setView(null); onChanged(); } }} />
  </Card>;
}

import type { AudienceLocale } from './audience-labels';

export const defaultOutreachLabels = {
  outreachTitle: 'Outreach', outreachHint: 'Written from the app’s own address. Each message goes out only when you confirm it.',
  unavailable: 'Outreach is not switched on for this app yet. Ask the platform team.',
  footerTitle: 'Who is writing', footerHint: 'Printed at the bottom of every message, with an unsubscribe link. Nothing can be sent before all three are filled.',
  name: 'Name', company: 'Company', postal: 'Postal address', saveFooter: 'Save', footerMissing: 'Fill in who is writing first.',
  draft: 'Draft', noDrafts: 'No draft yet', noDraftsDescription: 'Add a file to documents/outreach, with a Subject line, then the text.',
  recipients: 'Recipients', noRecipients: 'No recipient yet', recipient: 'Address', link: 'Link id', send: 'Send…', alreadySent: 'Already sent',
  quota: (left: number, max: number) => `${left} of ${max} sends left today`,
  confirmTitle: 'Send this message?', confirmDescription: 'It goes out exactly as shown, once, from the app’s address.', from: 'From', to: 'To', subject: 'Subject',
  confirm: 'Send now', cancel: 'Cancel', sending: 'Sending', preparing: 'Checking',
  sentOk: 'Sent', failed: 'It could not be sent.',
  logTitle: 'Send log', logEmpty: 'Nothing sent yet', when: 'When', status: 'Status', messageId: 'Message id',
  statuses: { sent: 'Sent', uncertain: 'Not confirmed', delivering: 'Sending', suppressed: 'Refused', failed: 'Failed' } as Record<string, string>,
  errors: {
    footer_missing: 'Fill in who is writing first.', suppressed: 'This address asked not to be written to again.', over_budget: 'Today’s 20 sends are used.',
    confirm_required: 'The confirmation expired. Start again.', unconfigured: 'Outreach is not switched on for this app.', 'delivery-uncertain': 'The delivery could not be confirmed. Check the log before sending again.',
  } as Record<string, string>,
  inboxTitle: 'Inbox', inboxEmpty: 'No reply yet', inboxEmptyDescription: 'Replies to your messages arrive here.', unread: (n: number) => `${n} new`,
  from2: 'From', last: 'Last', open: 'Open', reply: 'Reply', replyPlaceholder: 'Your answer', review: 'Review the answer', close: 'Close',
  incoming: 'Received', outgoing: 'You', notAVerifiedSender: 'The sender’s address is not verified.',
  formatTime: (ms: number) => new Date(ms).toISOString().slice(0, 16).replace('T', ' '),
};
export type OutreachLabels = typeof defaultOutreachLabels;

const timeFormat = (locale: string) => {
  const formatter = new Intl.DateTimeFormat(locale, { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'UTC' });
  return (ms: number) => formatter.format(new Date(ms));
};

export const frenchOutreachLabels: OutreachLabels = {
